"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["7674"],{40917(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.item_formulario.tipo_renderizacao_incoerente_com_dominio","status":422,"titulo":"O tipo de campo n\xe3o \xe9 coerente com o dom\xednio do fato"},"descricao":{"codigo":"uniplus.item_formulario.tipo_renderizacao_incoerente_com_dominio","requisitos":["UNI-REQ-0143","UNI-REQ-0159"],"oQueAconteceu":["O `tipoRenderizacao` do item, ou do campo de um grupo, n\xe3o \xe9 o tipo que o fato admite no cat\xe1logo (UNI-REQ-0143). O \xfanico tipo admitido sai do dom\xednio, da cardinalidade e da fonte de valores do fato:","| Fato no cat\xe1logo | Tipo de campo |\\n| --- | --- |\\n| Dom\xednio booleano | `BOOLEANO` |\\n| Dom\xednio num\xe9rico | `NUMERO` |\\n| Texto, data ou endere\xe7o, de resposta \xfanica | `TEXTO`, `DATA` ou `ENDERECO`, nessa ordem |\\n| Categ\xf3rico de resposta \xfanica | `SELECAO_UNICA` |\\n| Categ\xf3rico de resposta m\xfaltipla | `SELECAO_MULTIPLA` |\\n| Categ\xf3rico de resposta \xfanica, de fonte munic\xedpio do Geo | `MUNICIPIO` |","O fato de texto, data ou endere\xe7o de resposta m\xfaltipla, e o munic\xedpio do Geo de resposta m\xfaltipla, n\xe3o admitem nenhum tipo de campo. A mensagem \xe9 \\"O tipo de campo \'`{tipo\\\\}`\' n\xe3o \xe9 coerente com o dom\xednio \'`{dom\xednio\\\\}`\', a cardinalidade \'`{cardinalidade\\\\}`\' e a fonte de valores \'`{fonte\\\\}`\' do fato \'`{c\xf3digo\\\\}`\'.\\", com o nome interno do tipo enviado, os dados do fato e `nenhuma` quando o fato n\xe3o tem fonte de valores.","A recusa vem na lista `errors` da resposta:","- na grava\xe7\xe3o dos itens do formul\xe1rio, `field` igual a `itens[i].tipoRenderizacao` ou `grupos[g].subitens[j].tipoRenderizacao`, depois da confer\xeancia de que o fato existe e \xe9 colet\xe1vel;\\n- nos modelos de formul\xe1rio, o mesmo caminho precedido de `conteudo.`;\\n- na aplica\xe7\xe3o de modelo, `field` igual a `modelo.itens[i].tipoRenderizacao`, com a posi\xe7\xe3o do item no modelo;\\n- na publica\xe7\xe3o inicial e na retifica\xe7\xe3o em ato \xfanico, em que cada item e campo de grupo gravados \xe9 reconferido contra o cat\xe1logo de hoje, porque a defini\xe7\xe3o do fato pode ter sido corrigida depois de o campo ser gravado (UNI-REQ-0159). O `field` come\xe7a por `formularios[FINALIDADE]`, como em `formularios[INSCRICAO].itens[0].tipoRenderizacao`, e a mensagem ganha o final \\"Item \'`{r\xf3tulo\\\\}`\' (fato \'`{c\xf3digo\\\\}`\'). Regrave o item no formul\xe1rio do processo.\\". Para o fato que alguma vers\xe3o publicada j\xe1 coletou, em vez da orienta\xe7\xe3o de regravar, a mensagem pede desfazer a corre\xe7\xe3o no cat\xe1logo enquanto o processo precisar ser retificado, porque o campo dele n\xe3o pode mudar.","Todas as recusas dos itens saem no mesmo lote, e nada \xe9 gravado. Na atualiza\xe7\xe3o de um modelo, um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Troque o `tipoRenderizacao` do item pelo tipo da tabela que corresponde ao fato, ou escolha outro fato. Se a corre\xe7\xe3o do fato no cat\xe1logo \xe9 a causa, no rascunho regrave o item com o novo tipo; em processo com vers\xe3o publicada que j\xe1 coletou o fato, a corre\xe7\xe3o do cat\xe1logo precisa ser desfeita enquanto a retifica\xe7\xe3o for necess\xe1ria."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o dos itens do formul\xe1rio","Aplica\xe7\xe3o de modelo de formul\xe1rio","Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Item formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);